// 1. Internal Linkage (C/C++ File Scope Encapsulation)
static int module_init_flag = 0; // Internal Linkage
static void setup_internal_resource() {
    if (!module_init_flag) {
        module_init_flag = 1;
        // Initialization code...
    }
}
// 'module_init_flag' is restricted to this translation unit

// 2. External Linkage (Declaration vs. Definition across units)
// In shared_defs.h:
extern const size_t MAX_POOL_SIZE;

// In shared_defs.c:
const size_t MAX_POOL_SIZE = 8192; // Definition

// 3. Thread Local Storage (Unique state per thread)
// Requires C11 or C++11
thread_local int thread_local_error_id = 0;

void log_thread_error(int code) {
    thread_local_error_id = code;
}

// 4. Anonymous Namespace (C++ replacement for file-scope static)
// Ensures internal linkage without polluting global scope
namespace {
    struct CacheData {};
    CacheData global_cache; // Internal linkage

    void process_data() {
        // Only visible here
    }
}
